function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},0);}
function ask(title,detail,{value='',accept='Save',input=true}={}){return new Promise(resolve=>{const d=$('promptDialog'),expandedHere=appMode()&&!uiExpanded;if(expandedHere)expandUI('prompt');$('promptTitle').textContent=title;$('promptDetail').textContent=detail||'';$('promptLabel').hidden=!input;$('promptInput').value=value;$('promptInput').required=input;$('promptAccept').textContent=accept;let result=null;const done=()=>{d.removeEventListener('close',done);if(expandedHere)restoreUI();resolve(result);};d.addEventListener('close',done);$('promptForm').onsubmit=e=>{e.preventDefault();result=input?$('promptInput').value.trim():true;if(input&&!result)return;d.close();};$('promptCancel').onclick=()=>d.close();d.showModal();setTimeout(()=>input?$('promptInput').focus():$('promptAccept').focus(),20);});}
function currentTab(){let t=state.tabs.find(x=>x.id===state.activeTab);if(!t){t=state.tabs[0];state.activeTab=t.id;}return t;}
function currentTheme(){return T.getTheme(p.theme,state.customThemes);}
function appMode(){return B.isAppInventor();}
const BASE_UI_MODES=new Set(['home','browser']);
const OVERLAY_UI_MODES=new Set(['settings','layout','command','modal','menu']);
function applyUIMode(){const visual=overlayUIMode||baseUIMode;root.dataset.uiMode=visual;root.dataset.baseUiMode=baseUIMode;root.dataset.browserActive=String(baseUIMode==='browser');root.dataset.tabsVisible='true';shell.dataset.uiMode=visual;}
