function navigate(raw){const url=C.resolve(raw,p.engine,p.customSearchPrefix);if(!url){toast('Enter a website or search term.');return;}const t=currentTab();C.navigateTab(t,url,true);setBaseUIMode('browser');if(p.rememberRecent)state.recent=C.recordRecent(state.recent,url,t.title);save();renderRecent();syncNavigation();renderTabs();$('addressBar').value=url;B.send('NAVIGATE',url);scheduleUIHeight();if(appMode())hidePreview();else showPreview(url);toast(appMode()?`Opening ${C.titleFromUrl(url)}`:`Previewing ${C.titleFromUrl(url)} for App Inventor`);}
function goHome(){setBaseUIMode('home');syncNavigation();renderTabs();syncBookmarkButton();hidePreview();B.send('HOME');scheduleUIHeight();focusOmnibox();}
function back(){const t=currentTab(),url=C.goHistory(t,-1);if(!url)return;setBaseUIMode('browser');save();syncNavigation();renderTabs();B.send('BACK',url);if(!appMode())showPreview(url);}
function forward(){const t=currentTab(),url=C.goHistory(t,1);if(!url)return;setBaseUIMode('browser');save();syncNavigation();renderTabs();B.send('FORWARD',url);if(!appMode())showPreview(url);}
