function syncNavigation(){const t=currentTab(),active=baseUIMode==='browser';applyUIMode();$('browserTabs').hidden=false;$('bookmarksBar').hidden=!active||!p.showBookmarksBar;$('backButton').disabled=!active||!C.canBack(t);$('forwardButton').disabled=!active||!C.canForward(t);$('refreshButton').disabled=!active||!t.url;if(document.activeElement!==$('addressBar'))$('addressBar').value=active?(t.url||''):'';$('clearAddressButton').hidden=!$('addressBar').value;syncBookmarkButton();scheduleUIHeight();}
function showPreview(url){if(!p.showPreview||(p.layoutHidden||[]).includes('preview'))return;const block=$('previewBlock');block.hidden=false;$('previewTitle').textContent=C.titleFromUrl(url);$('previewUrl').textContent=url;block.dataset.previewUrl=url;}
