function openExternal(){const url=currentTab().url||$('previewBlock').dataset.previewUrl;if(!url)return;if(appMode())B.send('OPEN_EXTERNAL',url);else window.open(url,'_blank','noopener,noreferrer');}

function tabIconText(t){return (t.title||C.titleFromUrl(t.url)||'N').trim().slice(0,1).toUpperCase()||'N';}
function fillIcon(node,src,text){const safe=src&&C.safeUrl(src),key=safe||`text:${text||'?'}`;if(node.dataset.iconKey===key)return;node.dataset.iconKey=key;node.replaceChildren();if(safe){const img=el('img');img.alt='';img.decoding='async';img.loading='lazy';img.src=safe;img.onerror=()=>{node.dataset.iconKey=`text:${text||'?'}`;node.replaceChildren(document.createTextNode(text||'?'));};node.append(img);}else node.textContent=text||'?';}
function renderTabs(){const list=$('tabList'),keep=new Set(),find=id=>[...list.children].find(n=>n.dataset.tabId===id);for(const t of state.tabs){keep.add(t.id);let n=find(t.id);if(!n){n=el('div','browser-tab');n.dataset.tabId=t.id;n.setAttribute('role','tab');n.tabIndex=0;n.draggable=true;n.innerHTML='<span class="tab-favicon"></span><span class="tab-title"></span><button class="tab-close" type="button" aria-label="Close tab" title="Close tab">×</button>';list.append(n);}n.setAttribute('aria-selected',String(t.id===state.activeTab));n.classList.toggle('active',t.id===state.activeTab);n.querySelector('.tab-title').textContent=t.title||C.titleFromUrl(t.url)||'New Tab';n.title=t.url||'New Tab';fillIcon(n.querySelector('.tab-favicon'),t.favicon,tabIconText(t));}for(const n of [...list.children])if(!keep.has(n.dataset.tabId))n.remove();for(const t of state.tabs){const n=find(t.id);if(n)list.append(n);}const active=find(state.activeTab);if(active&&active.scrollIntoView)active.scrollIntoView({block:'nearest',inline:'nearest'});}
function activateTab(id){const t=state.tabs.find(x=>x.id===id);if(!t||t.id===state.activeTab)return;state.activeTab=t.id;if(t.url)setBaseUIMode('browser');else setBaseUIMode('home');save();syncNavigation();renderTabs();if(t.url){B.send('NAVIGATE',t.url);if(!appMode())showPreview(t.url);}else{hidePreview();B.send('HOME');focusOmnibox();}scheduleUIHeight();}
function newTab(raw=''){if(state.tabs.length>=24){toast('Tab limit reached (24).');return;}const t=C.createTab();state.tabs.push(t);state.activeTab=t.id;const url=raw?C.resolve(raw,p.engine,p.customSearchPrefix):null;if(url){C.navigateTab(t,url,true);setBaseUIMode('browser');if(p.rememberRecent)state.recent=C.recordRecent(state.recent,url,t.title);}else setBaseUIMode('home');save();syncNavigation();renderTabs();renderRecent();if(url){B.send('NAVIGATE',url);if(!appMode())showPreview(url);}else{hidePreview();B.send('HOME');focusOmnibox();}scheduleUIHeight();}
function closeTab(id=state.activeTab){const i=state.tabs.findIndex(t=>t.id===id);if(i<0)return;if(state.tabs.length===1){state.tabs=[C.createTab()];state.activeTab=state.tabs[0].id;setBaseUIMode('home');save();syncNavigation();renderTabs();B.send('HOME');scheduleUIHeight();return;}const wasActive=id===state.activeTab;state.tabs.splice(i,1);if(wasActive){const next=state.tabs[Math.min(i,state.tabs.length-1)];state.activeTab=next.id;setBaseUIMode(next.url?'browser':'home');}save();syncNavigation();renderTabs();if(wasActive){const t=currentTab();if(t.url)B.send('NAVIGATE',t.url);else B.send('HOME');}scheduleUIHeight();}
async function closeOtherTabs(){if(state.tabs.length<=1)return;if(p.confirmCloseMultiple&&!await ask('Close other tabs?',`Close ${state.tabs.length-1} other tab${state.tabs.length===2?'':'s'}?`,{accept:'Close tabs',input:false}))return;const t=currentTab();state.tabs=[t];state.activeTab=t.id;save();syncNavigation();renderTabs();toast('Other tabs closed.');}
function reorderTab(fromId,toId){if(!fromId||!toId||fromId===toId)return;const from=state.tabs.findIndex(t=>t.id===fromId),to=state.tabs.findIndex(t=>t.id===toId);if(from<0||to<0)return;const [item]=state.tabs.splice(from,1);state.tabs.splice(to,0,item);save();renderTabs();}

const tabList=$('tabList');
tabList.addEventListener('click',e=>{const tab=e.target.closest('.browser-tab');if(!tab)return;if(e.target.closest('.tab-close'))closeTab(tab.dataset.tabId);else activateTab(tab.dataset.tabId);});
