tabList.addEventListener('keydown',e=>{const tab=e.target.closest('.browser-tab');if(!tab)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();activateTab(tab.dataset.tabId);}else if(e.key==='Delete'){e.preventDefault();closeTab(tab.dataset.tabId);}});
