function currentBookmark(){const u=currentTab().url;return u?state.bookmarks.find(b=>b.url===u):null;}
function syncBookmarkButton(){const b=$('bookmarkPageButton'),hit=currentBookmark(),menu=$('menuBookmarkPage');b.textContent=hit?'★':'☆';b.setAttribute('aria-label',hit?'Remove bookmark':'Bookmark this page');b.title=hit?'Remove bookmark':'Bookmark this page';b.disabled=!currentTab().url;if(menu){menu.firstChild.textContent=hit?'Remove bookmark ':'Bookmark page ';menu.disabled=!currentTab().url;}}
