function openBookmarkTarget(b){if(!b)return;if(p.bookmarkOpenBehavior==='new')newTab(b.url);else navigate(b.url);closeBookmarkFolderMenu();}
function renderBookmarks(){const bar=$('bookmarksBar'),list=$('bookmarkList');bar.hidden=baseUIMode!=='browser'||!currentTab().url||!p.showBookmarksBar;const key=`${p.showBookmarkFavicons}|${p.showBookmarkText}|`+state.bookmarks.map(b=>[b.id,b.label,b.url,b.icon,b.favicon,b.folder].join('~')).join('||');if(key===bookmarkRenderKey){scheduleUIHeight();return;}bookmarkRenderKey=key;const frag=document.createDocumentFragment(),seenFolders=new Set();for(const b of state.bookmarks){if(!b.folder){frag.append(makeBookmarkButton(b));continue;}if(seenFolders.has(b.folder))continue;seenFolders.add(b.folder);const items=state.bookmarks.filter(x=>x.folder===b.folder),f=btn('',()=>openBookmarkFolder(b.folder,items),'bookmark-folder');f.dataset.folder=b.folder;f.textContent=b.folder;frag.append(f);}list.replaceChildren(frag);scheduleUIHeight();}
function makeBookmarkButton(b){const n=btn('',()=>openBookmarkTarget(b),'bookmark-item');n.dataset.bookmarkId=b.id;n.draggable=true;n.title=`${b.label} — ${b.url}\nRight-click or hold to edit`;if(p.showBookmarkFavicons){const icon=el('span','bookmark-favicon');fillIcon(icon,b.favicon,bookmarkIconText(b));n.append(icon);}if(p.showBookmarkText||!p.showBookmarkFavicons)n.append(el('span','bookmark-label',b.label));return n;}
function openBookmarkFolder(folder,items){if(appMode()&&!uiExpanded)expandUI('bookmark-folder');const menu=$('bookmarkFolderMenu');menu.replaceChildren();for(const b of items){const n=btn(b.label,()=>openBookmarkTarget(b));n.dataset.bookmarkId=b.id;menu.append(n);}const edit=btn('Edit folder bookmarks',()=>{closeBookmarkFolderMenu();openSettings('browser');});menu.append(edit);menu.hidden=false;const anchor=[...$('bookmarkList').querySelectorAll('.bookmark-folder')].find(n=>n.dataset.folder===folder);if(anchor){const r=anchor.getBoundingClientRect();menu.style.left=`${Math.min(r.left,innerWidth-menu.offsetWidth-8)}px`;menu.style.top=`${Math.min(r.bottom+3,innerHeight-menu.offsetHeight-8)}px`;}}
