$('bookmarkList').addEventListener('contextmenu',e=>{const n=e.target.closest('.bookmark-item');if(!n)return;e.preventDefault();openBookmarkDialog(n.dataset.bookmarkId);});
let bookmarkHoldTimer=0;$('bookmarkList').addEventListener('pointerdown',e=>{const n=e.target.closest('.bookmark-item');if(!n)return;clearTimeout(bookmarkHoldTimer);bookmarkHoldTimer=setTimeout(()=>openBookmarkDialog(n.dataset.bookmarkId),560);});['pointerup','pointercancel','pointermove'].forEach(name=>$('bookmarkList').addEventListener(name,()=>clearTimeout(bookmarkHoldTimer),{passive:true}));
