$('bookmarkPageButton').onclick=toggleCurrentBookmark;$('addBookmarkButton').onclick=()=>openBookmarkDialog(null,currentTab().url);
$('bookmarkForm').onsubmit=e=>{e.preventDefault();const label=$('bookmarkName').value.trim(),url=C.resolve($('bookmarkUrl').value,p.engine,p.customSearchPrefix),folder=$('bookmarkFolder').value.trim(),icon=$('bookmarkIcon').value.trim()||label.slice(0,1).toUpperCase();if(!label||!url){$('bookmarkError').textContent='Enter a valid name and website.';return;}const old=editingBookmarkId?state.bookmarks.find(b=>b.id===editingBookmarkId):null,item={id:old?.id||C.uid('bookmark'),label,url,folder,icon,favicon:old?.favicon||''};if(old)Object.assign(old,item);else state.bookmarks.push(item);state.bookmarks=C.sanitizeBookmarks(state.bookmarks);bookmarkRenderKey='';$('bookmarkDialog').close();save();renderBookmarks();syncBookmarkButton();toast('Bookmark saved.');};
