$('menuNewTab').onclick=()=>{closeBrowserMenu();newTab();};$('menuBookmarkPage').onclick=()=>{closeBrowserMenu();toggleCurrentBookmark();};$('menuToggleBookmarks').onclick=()=>{closeBrowserMenu();toggleBookmarksBar();};$('menuBack').onclick=()=>{closeBrowserMenu();back();};$('menuForward').onclick=()=>{closeBrowserMenu();forward();};$('menuRefresh').onclick=()=>{closeBrowserMenu();refresh();};$('menuHome').onclick=()=>{closeBrowserMenu();goHome();};$('menuCloseTab').onclick=()=>{closeBrowserMenu();closeTab();};$('menuCloseOtherTabs').onclick=()=>{closeBrowserMenu();closeOtherTabs();};$('menuBrowserSettings').onclick=()=>{closeBrowserMenu();openSettings('browser');};
document.addEventListener('click',e=>{if(!e.target.closest('#browserMenu')&&!e.target.closest('#browserMenuButton'))closeBrowserMenu();if(!e.target.closest('#bookmarkFolderMenu')&&!e.target.closest('.bookmark-folder'))closeBookmarkFolderMenu();});

$('addressForm').addEventListener('submit',e=>{e.preventDefault();navigate($('addressBar').value);});$('backButton').onclick=back;$('forwardButton').onclick=forward;$('refreshButton').onclick=refresh;$('homeButton').onclick=goHome;$('externalButton').onclick=openExternal;$('previewExternal').onclick=openExternal;$('clearAddressButton').onclick=()=>{$('addressBar').value='';$('addressBar').focus();$('clearAddressButton').hidden=true;};$('addressBar').addEventListener('input',()=>{$('clearAddressButton').hidden=!$('addressBar').value;});
window.addEventListener('blobby:appmessage',e=>{const {command,payload}=e.detail,t=currentTab();if(command==='URL'){const u=C.safeUrl(payload);if(u){if(t.history[t.historyIndex]!==u)C.navigateTab(t,u,true);else t.url=u;if(!t.title||t.title==='New Tab')t.title=C.titleFromUrl(u);$('addressBar').value=u;save();syncNavigation();renderTabs();renderBookmarks();}}else if(command==='TITLE'){t.title=String(payload||'').slice(0,80)||C.titleFromUrl(t.url);save();renderTabs();}else if(command==='FAVICON'){const u=C.safeUrl(payload);t.favicon=u||'';save();renderTabs();renderBookmarks();}else if(command==='HOME_SHOWN'){hidePreview();}else if(command==='CONNECTED'){syncBridgeBadge();}});

function iconFor(link){return (link.icon||link.label.slice(0,1)||'?').slice(0,4);}
function renderShortcuts(){const grid=$('shortcutGrid');grid.replaceChildren();const groups=new Map();for(const link of state.links){const f=link.folder||'';if(!groups.has(f))groups.set(f,[]);groups.get(f).push(link);}for(const [folder,links] of groups){if(folder)grid.append(el('div','shortcut-folder',folder));for(const link of links){const a=btn('',()=>navigate(link.url),'shortcut-tile');a.title=link.url;a.append(el('span','shortcut-icon',iconFor(link)),el('span','shortcut-name',link.label));grid.append(a);}}if(!state.links.length)grid.append(el('p','empty-state','No shortcuts yet. Add one in Settings.'));}
function renderRecent(){const box=$('recentList');box.replaceChildren();if(!state.recent.length){box.append(el('p','empty-state','Pages you open from blobby.vip will appear here.'));return;}for(const item of state.recent.slice(0,p.performance?5:10)){const row=el('div','recent-row'),main=btn('',()=>navigate(item.url),'recent-main');main.append(el('strong','',item.label),el('small','',item.url));row.append(main,el('time','',new Date(item.time).toLocaleDateString(undefined,{month:'short',day:'numeric'})));box.append(row);}}
$('clearRecentButton').onclick=async()=>{if(await ask('Clear recent pages?','This removes the recent-page list saved on this device.',{accept:'Clear',input:false})){state.recent=[];renderRecent();save();toast('Recent pages cleared.');}};
function openShortcut(index=-1){editingShortcut=index;const x=index>=0?state.links[index]:{label:'',url:'',folder:'',icon:''};$('shortcutTitle').textContent=index>=0?'Edit shortcut':'Add shortcut';$('shortcutName').value=x.label;$('shortcutUrl').value=x.url;$('shortcutFolder').value=x.folder||'';$('shortcutIcon').value=x.icon||'';$('deleteShortcutButton').hidden=index<0;$('shortcutError').textContent='';$('shortcutDialog').showModal();setTimeout(()=>$('shortcutName').focus(),20);}
$('manageShortcutsButton').onclick=()=>openSettings('shortcuts');
$('shortcutForm').onsubmit=e=>{e.preventDefault();const label=$('shortcutName').value.trim(),url=C.resolve($('shortcutUrl').value,p.engine,p.customSearchPrefix),folder=$('shortcutFolder').value.trim(),icon=$('shortcutIcon').value.trim()||label.slice(0,1).toUpperCase();if(!label||!url){$('shortcutError').textContent='Enter a valid name and website.';return;}const item={label,url,folder,icon};if(editingShortcut>=0)state.links[editingShortcut]=item;else state.links.push(item);$('shortcutDialog').close();renderShortcuts();renderShortcutSettings();save();toast('Shortcut saved.');};
$('deleteShortcutButton').onclick=async()=>{if(editingShortcut<0)return;if(await ask('Delete shortcut?','This removes it from Quick access.',{accept:'Delete',input:false})){state.links.splice(editingShortcut,1);$('shortcutDialog').close();renderShortcuts();renderShortcutSettings();save();toast('Shortcut deleted.');}};
function moveShortcut(index,delta){const j=index+delta;if(j<0||j>=state.links.length)return;const [x]=state.links.splice(index,1);state.links.splice(j,0,x);renderShortcuts();renderShortcutSettings();save();}

const categories=[['appearance','Appearance'],['themes','Themes'],['background','Background'],['layout','Layout'],['cursor','Cursor'],['ambient','Ambient'],['homepage','Homepage'],['shortcuts','Shortcuts'],['browser','Browser'],['performance','Performance'],['profiles','Profiles'],['accessibility','Accessibility'],['advanced','Advanced']];
function panel(id){return $('settings-'+id);}
function group(parent,title,description=''){const g=el('section','setting-group');g.dataset.settingSearch=(title+' '+description).toLowerCase();g.append(el('h4','',title));if(description)g.append(el('p','setting-help',description));parent.append(g);return g;}
function row(parent,label,description=''){const r=el('div','setting-row');r.dataset.settingSearch=(label+' '+description).toLowerCase();const copy=el('div','setting-copy');copy.append(el('strong','',label));if(description)copy.append(el('small','',description));r.append(copy);parent.append(r);return r;}
function toggle(parent,key,label,description='',scope=p){const r=row(parent,label,description),i=el('input','switch-input');i.type='checkbox';i.checked=!!scope[key];i.setAttribute('aria-label',label);i.addEventListener('change',()=>{scope[key]=i.checked;changed();});r.append(i);return i;}
function range(parent,key,label,min,max,step=1,unit='',scope=p){const r=row(parent,label),wrap=el('div','range-control'),i=el('input');i.type='range';i.min=min;i.max=max;i.step=step;i.value=scope[key];const out=el('output','',`${scope[key]}${unit}`);i.addEventListener('input',()=>{scope[key]=Number(i.value);out.textContent=`${i.value}${unit}`;changed(false);});i.addEventListener('change',()=>save());wrap.append(i,out);r.append(wrap);return i;}
function select(parent,key,label,options,scope=p){const r=row(parent,label),s=el('select');for(const [v,n] of options){const o=el('option','',n);o.value=v;s.append(o);}s.value=scope[key];s.addEventListener('change',()=>{scope[key]=s.value;changed();});r.append(s);return s;}
function color(parent,key,label,scope=p,onChange=null){const r=row(parent,label),wrap=el('div','color-control'),c=el('input'),text=el('input');c.type='color';c.value=scope[key];text.value=scope[key];text.maxLength=7;const applyColor=v=>{if(!/^#[0-9a-f]{6}$/i.test(v))return;scope[key]=v.toLowerCase();c.value=scope[key];text.value=scope[key];onChange?onChange():changed();};c.oninput=()=>applyColor(c.value);text.onchange=()=>applyColor(text.value);wrap.append(c,text);r.append(wrap);return c;}
function actionRow(parent,...buttons){const r=el('div','settings-actions');buttons.forEach(b=>r.append(b));parent.append(r);return r;}
function makeSettings(){const nav=$('settingsNav'),panels=$('settingsPanels');nav.replaceChildren();panels.replaceChildren();for(const [id,name] of categories){const n=btn(name,()=>showSettings(id),'settings-nav-button');n.dataset.category=id;nav.append(n);const pn=el('section','settings-panel');pn.id='settings-'+id;pn.dataset.category=id;pn.append(el('h3','settings-title',name));panels.append(pn);}buildAppearance();buildThemes();buildBackground();buildLayout();buildCursor();buildAmbient();buildHomepage();buildShortcuts();buildBrowser();buildPerformance();buildProfiles();buildAccessibility();buildAdvanced();showSettings(activeSettings);}
